import { useCallback } from 'react';

import { useTicketMutator } from '@eventespresso/edtr-services';
import { useTimeZoneTime } from '@eventespresso/services';
import { InlineDateRangeEdit } from '@eventespresso/ui-components';

import type { Ticket } from '@eventespresso/edtr-services';
import type { Datetime } from '@eventespresso/types';

interface EditableDateTimeProps {
	ticket: Ticket;
	dateField: Datetime.DateField;
}

const EditableDateTime: React.FC<EditableDateTimeProps> = ({ ticket, dateField }) => {
	const { updateEntity } = useTicketMutator(ticket.id);
	const { siteTimeToUtc } = useTimeZoneTime();

	const onChange = useCallback(
		([startDate, endDate]) => {
			updateEntity({
				id: ticket.id,
				startDate: siteTimeToUtc(startDate).toISOString(),
				endDate: siteTimeToUtc(endDate).toISOString(),
			});
		},
		[updateEntity, ticket.id, siteTimeToUtc]
	);

	return (
		<InlineDateRangeEdit
			id={ticket.id}
			date={ticket?.[dateField]}
			startDate={ticket.startDate}
			endDate={ticket.endDate}
			onChange={onChange}
			dateField={dateField}
		/>
	);
};

export default EditableDateTime;
