import { useEffect } from 'react';

import useOnDelete from './useOnDelete';
import useDeletableTickets from './useDeletableTickets';
import useDeleteDialog from './useDeleteDialog';

import type { OnDeleteProps } from './types';

type DeleteProps = Pick<OnDeleteProps, 'areTrashedTickets' | 'onClose'>;

const Delete: React.FC<DeleteProps> = ({ areTrashedTickets, onClose }) => {
	const { deletableIds, lastRelatedCount, lockedCount, hasNoDeletableTickets } =
		useDeletableTickets(areTrashedTickets);

	const onDelete = useOnDelete({ idsToDelete: deletableIds, areTrashedTickets, onClose });

	const { confirmationDialog, onOpen } = useDeleteDialog({
		areTrashedTickets,
		hasNoDeletableTickets,
		lockedCount,
		lastRelatedCount,
		onDelete,
		onClose,
	});

	// eslint-disable-next-line react-hooks/exhaustive-deps
	useEffect(() => onOpen(), []);

	return <>{confirmationDialog}</>;
};

export default Delete;
