import { useMemo } from 'react';

import { __, _n, sprintf } from '@eventespresso/i18n';
import { useConfirmationDialog } from '@eventespresso/ui-components';

type Props = {
	areTrashedTickets: boolean;
	hasNoDeletableTickets: boolean;
	lockedCount: number;
	lastRelatedCount: number;
	onDelete: () => void;
	onClose: () => void;
};

const useDeleteDialog = ({
	areTrashedTickets,
	hasNoDeletableTickets,
	lockedCount,
	lastRelatedCount,
	onDelete,
	onClose,
}: Props) => {
	const title = useMemo(() => {
		if (hasNoDeletableTickets) {
			return __('Cannot Delete Tickets');
		}

		return areTrashedTickets ? __('Delete Tickets Permanently') : __('Trash Tickets');
	}, [areTrashedTickets, hasNoDeletableTickets]);

	const skippedReasons = useMemo(
		() =>
			[
				lockedCount > 0
					? sprintf(
							/* translators: %d: number of tickets with registrations that will be skipped */
							_n(
								'%d ticket has existing registrations and cannot be permanently deleted.',
								'%d tickets have existing registrations and cannot be permanently deleted.',
								lockedCount
							),
							lockedCount
						)
					: null,
				lastRelatedCount > 0
					? sprintf(
							/* translators: %d: number of tickets that are last-linked to a datetime and will be skipped */
							_n(
								'%d ticket is the only ticket assigned to one or more datetimes and cannot be permanently deleted.',
								'%d tickets are the only tickets assigned to one or more datetimes and cannot be permanently deleted.',
								lastRelatedCount
							),
							lastRelatedCount
						)
					: null,
			].filter(Boolean) as string[],
		[lockedCount, lastRelatedCount]
	);

	const mainText = useMemo(() => {
		if (hasNoDeletableTickets) {
			return __('None of the selected tickets can be permanently deleted.');
		}

		return areTrashedTickets
			? __('Are you sure you want to permanently delete these tickets? This action can NOT be undone!')
			: __('Are you sure you want to trash these tickets?');
	}, [areTrashedTickets, hasNoDeletableTickets]);

	const message = useMemo(
		() => (
			<>
				<p>{mainText}</p>
				{skippedReasons.length > 0 && (
					<>
						<p>
							<strong>{__('Note:')}</strong>{' '}
							{hasNoDeletableTickets
								? __('These tickets cannot be deleted:')
								: __('The following tickets will be skipped:')}
						</p>
						{skippedReasons.map((reason) => (
							<p key={reason}>
								{'• '}
								{reason}
							</p>
						))}
					</>
				)}
			</>
		),
		[mainText, skippedReasons, hasNoDeletableTickets]
	);

	return useConfirmationDialog({
		message,
		title,
		onConfirm: hasNoDeletableTickets ? onClose : onDelete,
		onCancel: onClose,
		yesButtonText: hasNoDeletableTickets ? __('Close') : undefined,
	});
};

export default useDeleteDialog;
