import { useMemo } from 'react';

import { useBulkEdit } from '@eventespresso/services';
import { useTickets } from '@eventespresso/edtr-services';
import { isLocked } from '@eventespresso/predicates';
import { useFilterDeletableEntities } from '@edtrHooks/deletableEntities';

const useDeletableTickets = (areTrashedTickets: boolean) => {
	const { getSelected } = useBulkEdit();
	const selectedIds = getSelected();

	// Locked check: tickets with registrations cannot be permanently deleted.
	const selectedTickets = useTickets((ticket) => areTrashedTickets && selectedIds.includes(ticket.id));
	const lockedIds = useMemo(() => selectedTickets.filter(isLocked).map((t) => t.id), [selectedTickets]);

	// Non-locked IDs are candidates for the last-related check.
	const nonLockedIds = useMemo(() => selectedIds.filter((id) => !lockedIds.includes(id)), [selectedIds, lockedIds]);

	// Last-related check: only runs for permanent delete; pass [] to skip when just trashing.
	const lastRelatedIds = useFilterDeletableEntities('tickets', areTrashedTickets ? nonLockedIds : [], 'datetimes');

	const deletableIds = areTrashedTickets ? lastRelatedIds : selectedIds;
	const lockedCount = lockedIds.length;
	const lastRelatedCount = areTrashedTickets ? nonLockedIds.length - lastRelatedIds.length : 0;
	const hasNoDeletableTickets = areTrashedTickets && deletableIds.length === 0;

	return {
		deletableIds,
		lastRelatedCount,
		lockedCount,
		hasNoDeletableTickets,
	};
};

export default useDeletableTickets;
